import solution
from solution import check


def test_issue_example():
    """Example: check("01010101010") == "Yes"."""
    assert check("01010101010") == "Yes"  # 5+6=11 chars all in {'0','1'} -> "Yes"


def test_issue_single_zero():
    """A single "0" is a binary string so check returns "Yes"."""
    assert check("0") == "Yes"  # 1 char, 1==1 in {'0','1'} -> "Yes"


def test_issue_single_one():
    """A single "1" is a binary string so check returns "Yes"."""
    assert check("1") == "Yes"  # 1 char, 1==1 in {'0','1'} -> "Yes"


def test_issue_long_alternating():
    """A long string of only '0' and '1' is binary so returns "Yes"."""
    assert check("01" * 100) == "Yes"  # 2*100=200 chars all in {'0','1'} -> "Yes"


def test_issue_char_just_below_zero():
    """'/' is just below '0' so "/" is not binary."""
    assert check("/") == "No"  # ord('/')=47 is 48-1=47, not in {'0','1'} -> "No"


def test_issue_char_just_above_one():
    """'2' is just above '1' so "2" is not binary."""
    assert check("2") == "No"  # ord('2')=50 is 49+1=50, not in {'0','1'} -> "No"


def test_issue_middle_digit_intruder():
    """String "0102010" contains '2' so is not binary."""
    assert check("0102010") == "No"  # 6+1=7 chars, one '2' not in {'0','1'} -> "No"


def test_issue_letter_intruder():
    """String with a letter is not a binary string."""
    assert check("010a010") == "No"  # 6+1=7 chars, one 'a' not in {'0','1'} -> "No"


def test_issue_space_inside():
    """String with a space is not a binary string."""
    assert check("01 01") == "No"  # 2+1+2=5 chars, one ' ' not in {'0','1'} -> "No"


def test_issue_empty_string_handled():
    """Edge case: empty string must return a verdict without error."""
    assert check("") in ("Yes", "No")  # 0 chars edge, must be one of 2 verdicts


def test_contract_check_is_callable():
    """Public interface requires 'def check(string)' in solution."""
    assert callable(solution.check)  # 1 required callable named check


def test_contract_return_type_is_str():
    """Example shows check returns a string verdict like "Yes"."""
    assert isinstance(check("0101"), str)  # 2+2=4 chars all binary, type is str
